import { readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { components, profiles } from './catalog.mjs'

const root = fileURLToPath(new URL('../../', import.meta.url))
const header =
  '// Generated by scripts/style-slots/generate.mjs; edit catalog.mjs, not this file.\n'
const quoted = JSON.stringify
const key = (name) => (name.includes('-') ? `'${name}'` : name)

export function validateCatalog(catalog = components, facts = profiles) {
  for (const [component, slots] of Object.entries(catalog)) {
    if (!/^[A-Z][A-Za-z]+$/.test(component)) throw new Error(`Invalid component: ${component}`)
    const names = new Set()
    for (const slot of slots) {
      if (names.has(slot.classProp)) throw new Error(`Duplicate ${component}.${slot.classProp}`)
      names.add(slot.classProp)
      if (
        !/^(className|[a-zA-Z]+ClassName)$/.test(slot.classProp) ||
        (slot.styleProp !== null &&
          (typeof slot.styleProp !== 'string' || !/^[a-zA-Z]+$/.test(slot.styleProp)))
      )
        throw new Error(`Invalid slot: ${component}.${slot.classProp}`)
      if (slot.styleProp === null && (slot.lowering !== 'component-managed' || !slot.reason))
        throw new Error(`Missing style mapping reason: ${component}.${slot.classProp}`)
      if (!['root', 'secondary', 'component-managed', 'web-only'].includes(slot.lowering))
        throw new Error(`Missing lowering: ${component}.${slot.classProp}`)
      if (slot.profile && !facts[slot.profile]) throw new Error(`Unknown profile: ${slot.profile}`)
      if (slot.events !== undefined && (slot.events !== 'unavailable' || slot.callback))
        throw new Error(`Conflicting event owner: ${component}.${slot.classProp}`)
      if (
        slot.profile &&
        !slot.callback &&
        Object.values(facts[slot.profile].facts).some((binding) => typeof binding !== 'boolean')
      )
        throw new Error(`Facts need a consuming callback: ${component}.${slot.classProp}`)
      if (
        slot.callback &&
        (!slot.profile || typeof slot.focus !== 'boolean' || typeof slot.pointer !== 'boolean')
      )
        throw new Error(`Incomplete owner: ${component}.${slot.classProp}`)
      if (slot.callback && !['root', 'secondary'].includes(slot.lowering))
        throw new Error(`Callback has no compiler route: ${component}.${slot.classProp}`)
      if (
        slot.placeholderColorProp &&
        (!slot.callback || !/^hozo[A-Za-z]+PlaceholderTextColor$/.test(slot.placeholderColorProp))
      )
        throw new Error(`Invalid placeholder prop owner: ${component}.${slot.classProp}`)
      if (slot.scrollYProp && !/^hozo(?:[A-Z][a-z]+)?ScrollY$/.test(slot.scrollYProp))
        throw new Error(`Invalid scroll prop owner: ${component}.${slot.classProp}`)
      if (slot.backdropStyleProp && slot.backdropStyleProp !== 'hozoBackdropStyle')
        throw new Error(`Invalid backdrop prop owner: ${component}.${slot.classProp}`)
      if (
        ![slot.owner, slot.gate, slot.composition].every(
          (value) => typeof value === 'string' && value.length,
        )
      )
        throw new Error(`Missing owner/gate/composition: ${component}.${slot.classProp}`)
      if (slot.owner === 'pending-audit' && (slot.callback || slot.profile))
        throw new Error(`Pending owner cannot claim state support: ${component}.${slot.classProp}`)
      if (slot.lowering === 'web-only' && !slot.reason)
        throw new Error(`Missing reason: ${component}.${slot.classProp}`)
    }
  }
  for (const [name, profile] of Object.entries(facts))
    for (const [fact, binding] of Object.entries(profile.facts)) {
      if (!['disabled', 'enabled', 'readOnly'].includes(fact) && !/^aria-[a-z]+$/.test(fact))
        throw new Error(`Unknown fact: ${name}.${fact}`)
      if (typeof binding !== 'boolean' && !/^__hozoSlot[A-Za-z]+$/.test(binding?.alias))
        throw new Error(`Invalid binding: ${name}.${fact}`)
    }
}

function condition(fact) {
  if (fact.startsWith('aria-')) return `Condition::Aria(state) if state == ${quoted(fact.slice(5))}`
  return {
    disabled: 'Condition::Disabled',
    enabled: 'Condition::Enabled',
    readOnly: 'Condition::FormState(FormState::ReadOnly)',
  }[fact]
}

export function outputs(catalog = components, facts = profiles) {
  validateCatalog(catalog, facts)
  const mappings = Object.entries(catalog).flatMap(([component, slots]) => {
    const secondary = slots.filter((slot) => slot.lowering === 'secondary')
    return secondary.length
      ? [
          `            Self::${component} => &[\n${secondary.map((slot) => `                ClassSlot { class_prop: ${quoted(slot.classProp)}, style_prop: ${quoted(slot.styleProp)} },`).join('\n')}\n            ],`,
        ]
      : []
  })
  // A root whose owner the catalog has audited is a real element the
  // component draws, so the Web asks that element whether it is disabled.
  const audited = Object.entries(catalog).flatMap(([component, slots]) =>
    slots.some((slot) => slot.lowering === 'root' && slot.owner !== 'pending-audit')
      ? [`Self::${component}`]
      : [],
  )
  const constantRoots = Object.entries(catalog).flatMap(([component, slots]) =>
    slots.some((slot) => slot.lowering === 'root' && slot.events === 'unavailable' && slot.profile)
      ? [`Self::${component}`]
      : [],
  )
  const ir = `${header}use crate::{ClassSlot, Primitive};

impl Primitive {
    /// Class lists besides className. One catalog row names a class prop and
    /// the Native style prop; adding a second element does not add a code path.
    pub fn class_slots(self) -> &'static [ClassSlot] {
        match self {
${mappings.join('\n')}
            _ => &[],
        }
    }

    /// Whether \`className\` lands on an element the catalog has audited -- a
    /// real DOM element the component draws, which keeps its own \`disabled\`
    /// -- rather than on a host carrying Hozo's disabled marker. Web CSS then
    /// asks that element (\`:disabled\`, \`:enabled\`), as it does a secondary
    /// slot's owner: a span or a div is neither (#993).
    pub fn root_owner_is_audited(self) -> bool {
        ${audited.length ? `matches!(self, ${audited.join(' | ')})` : 'false'}
    }

    /// A constant non-control root uses actual DOM form predicates for
    /// candidate classes too, without adding an event owner or callback.
    pub fn root_owner_has_constant_facts(self) -> bool {
        ${constantRoots.length ? `matches!(self, ${constantRoots.join(' | ')})` : 'false'}
    }
}
`
  const semantics = []
  const parameters = []
  const interactions = []
  const unavailableEvents = []
  const constantFacts = []
  const placeholderProps = []
  const scrollProps = []
  const backdropProps = []
  for (const [component, slots] of Object.entries(catalog)) {
    const byProfile = new Map()
    const supplied = new Map()
    for (const slot of slots) {
      if (slot.backdropStyleProp)
        backdropProps.push(
          `        (Primitive::${component}, ${quoted(slot.classProp)}) => Some(${quoted(slot.backdropStyleProp)}),`,
        )
      if (slot.scrollYProp)
        scrollProps.push(
          `        (Primitive::${component}, ${quoted(slot.classProp)}) => Some(${quoted(slot.scrollYProp)}),`,
        )
      if (slot.placeholderColorProp)
        placeholderProps.push(
          `        (Primitive::${component}, ${quoted(slot.classProp)}) => Some(${quoted(slot.placeholderColorProp)}),`,
        )
      if (slot.events === 'unavailable' && slot.profile && !slot.callback) {
        constantFacts.push(
          `        (Primitive::${component}, ${quoted(slot.classProp)}) => Some(${quoted(
            `{ ${Object.entries(facts[slot.profile].facts)
              .map(([fact, value]) => `${key(fact)}: ${value}`)
              .join(', ')} }`,
          )}),`,
        )
      }
      if (slot.events === 'unavailable')
        unavailableEvents.push(`        (Primitive::${component}, ${quoted(slot.classProp)})`)
      if (slot.profile) {
        const grouped = byProfile.get(slot.profile) ?? []
        grouped.push(quoted(slot.classProp))
        byProfile.set(slot.profile, grouped)
      }
      if (slot.callback) {
        const aliases = Object.entries(facts[slot.profile].facts)
          .filter(([, binding]) => typeof binding !== 'boolean')
          .map(([fact, binding]) => `, ${key(fact)}: ${binding.alias}`)
          .join('')
        if (aliases) {
          const names = supplied.get(aliases) ?? []
          names.push(quoted(slot.classProp))
          supplied.set(aliases, names)
        }
        interactions.push(
          `        (Primitive::${component}, ${quoted(slot.classProp)}) => Some(InteractionSlot { style_prop: ${quoted(slot.callback)}, focus: ${slot.focus}, pointer: ${slot.pointer}, optional_owner: ${slot.optionalOwner ? `Some(${quoted(slot.optionalOwner)})` : 'None'} }),`,
        )
      }
    }
    for (const [profile, names] of byProfile) {
      semantics.push(
        `        // ${facts[profile].note}\n        (Primitive::${component}, ${names.join(' | ')}) => match condition {\n${Object.entries(
          facts[profile].facts,
        )
          .map(
            ([fact, binding]) =>
              `            ${condition(fact)} => Some(${quoted(typeof binding === 'boolean' ? String(binding) : binding.alias)}),`,
          )
          .join('\n')}\n            _ => None,\n        },`,
      )
    }
    for (const [aliases, names] of supplied)
      parameters.push(
        `        (Primitive::${component}, ${names.join(' | ')}) => ${quoted(aliases)},`,
      )
  }
  const native = `${header}
pub(super) fn semantic_binding(primitive: Primitive, class_prop: &str, condition: &Condition) -> Option<&'static str> {
    match (primitive, class_prop) {
${semantics.join('\n')}
        _ => None,
    }
}

pub(super) fn semantic_parameters(primitive: Primitive, class_prop: &str) -> &'static str {
    match (primitive, class_prop) {
${parameters.join('\n')}
        _ => "",
    }
}

pub(super) fn interaction_slot(primitive: Primitive, class_prop: &str) -> Option<InteractionSlot> {
    match (primitive, class_prop) {
${interactions.join('\n')}
        _ => None,
    }
}

pub(super) fn events_unavailable(primitive: Primitive, class_prop: &str) -> bool {
    matches!((primitive, class_prop),
${unavailableEvents.join('\n        | ')}
    )
}

pub(super) fn constant_facts(primitive: Primitive, class_prop: &str) -> Option<&'static str> {
    match (primitive, class_prop) {
${constantFacts.join('\n')}
        _ => None,
    }
}

pub(super) fn placeholder_color_prop(primitive: Primitive, class_prop: &str) -> Option<&'static str> {
    match (primitive, class_prop) {
${placeholderProps.join('\n')}
        _ => None,
    }
}

pub(super) fn scroll_y_prop(primitive: Primitive, class_prop: &str) -> Option<&'static str> {
    match (primitive, class_prop) {
${scrollProps.join('\n')}
        _ => None,
    }
}

pub(super) fn backdrop_style_prop(primitive: Primitive, class_prop: &str) -> Option<&'static str> {
    match (primitive, class_prop) {
${backdropProps.join('\n')}
        _ => None,
    }
}
`
  const ts = `${header}// Type-only facts. Absence from a profile is unavailable, not false. Actual
// components still calculate facts from their own host/shape and existing events.
${Object.entries(facts)
  .map(
    ([name, profile]) =>
      `\n/** ${profile.note} */\nexport interface ${name}SlotFacts {\n  readonly [fact: string]: unknown\n${Object.entries(
        profile.facts,
      )
        .map(
          ([fact, binding]) =>
            `  ${key(fact)}: ${typeof binding === 'boolean' ? String(binding) : 'boolean'}`,
        )
        .join('\n')}\n}\n`,
  )
  .join('')}`
  return {
    'crates/hozo_ir/src/class_slots.rs': ir,
    'crates/hozo_native/src/pattern_contracts.rs': native,
    'packages/patterns/src/slot-facts.native.ts': ts,
  }
}

export function checkGenerated() {
  return Object.entries(outputs())
    .filter(
      ([file, expected]) =>
        readFileSync(path.join(root, file), 'utf8').replaceAll('\r\n', '\n') !== expected,
    )
    .map(([file]) => file)
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  if (process.argv.includes('--check')) {
    const stale = checkGenerated()
    if (stale.length)
      throw new Error(
        `Stale style-slot output: ${stale.join(', ')}; run node scripts/style-slots/generate.mjs`,
      )
    console.log('Style-slot generated files are current')
  } else {
    for (const [file, content] of Object.entries(outputs()))
      writeFileSync(path.join(root, file), content)
  }
}
